    {
        //onFrontDoorToggleClicked
        //When front_door_toggle clicked call virtual function
        //Call onFrontDoorToggleClicked
        onFrontDoorToggleClicked();
    }
    if (&src == &back_door_toggle)
    {
        //onBackDoorToggleClicked
        //When back_door_toggle clicked call virtual function
        //Call onBackDoorToggleClicked
        onBackDoorToggleClicked();
    }
    if (&src == &garage_toggle)
    {
        //onGarageToggleClicked
        //When garage_toggle clicked call virtual function
        //Call onGarageToggleClicked
        onGarageToggleClicked();
    }
    if (&src == &alarm_toggle)
    {
        //onAlarmToggleClicked
        //When alarm_toggle clicked call virtual function
        //Call onAlarmToggleClicked
        onAlarmToggleClicked();
    }
    if (&src == &lock_all_button)
    {
        //onLockAllToggleClicked
        //When lock_all_button clicked call virtual function
        //Call onLockAllToggleClicked
        onLockAllToggleClicked();
    }
